package net.minecraft.core.registries;public class BuiltInRegistries {public static final EntityRegistry BLOCK=new EntityRegistry();public static final EntityRegistry ENTITY_TYPE=new EntityRegistry();public static class EntityRegistry {public boolean containsKey(Object id){return true;}public Object get(Object id){return new EntityType(id.toString());}public Object getKey(Object entity){return net.minecraft.resources.ResourceLocation.parse(entity.toString());}}public record EntityType(String id){public Object create(Object world){dev.zomboid.clans.PveChecks.Mob mob=new dev.zomboid.clans.PveChecks.Mob((dev.zomboid.clans.PveChecks.World)world);mob.type=id;return mob;}}public static final Registry ITEM=new Registry();public static class Registry {public static java.util.Set<String> modKeys=new java.util.HashSet<>();public boolean containsKey(Object id){return id.toString().startsWith("minecraft:")||modKeys.contains(id.toString());}public net.minecraft.world.item.Item get(net.minecraft.resources.ResourceLocation loc){return loc.toString().startsWith("missing:")?net.minecraft.world.item.Items.AIR:new net.minecraft.world.item.Item(loc.toString());}}}